// TH15 Extra st07.ecl MainSub04 (source 1206-1221) -> th15_s7_w05.
// MainSub04 spawns the last GirlA03 formation before the midboss:
//   F0 starts at 1.6 and grows by 0.013 after every pair.
//   left  = enmCreate (-150 + RANDF2*8, -16), right = enmCreateM (+150 + RANDF2*8, -16),
//   alternating every 20 frames, 40 pairs. Parent is the stage, so x/y are world coords.
// Each GirlA03 moves/fires as GirlA03_at / GirlA03_at2 (source 219-266).

const TIME_LIMIT: int = 2424;      // 120 opening + 2300 source-window estimate + 4 startup
const OPENING_BUFFER: int = 120;

// GirlA03_at2: 10 volleys, each a 16-way ring with a fresh RANDRAD base.
// Source etSprite(0,8,6) -> TH15_RICE (480), color 6.
// Source etSpeed(0,F0,2.2) with M=1 uses F0. EX type2 a=1 is the birth ANIM:
// per approved policy the animation is omitted but its position -= 4*velocity offset is kept.
async sub girl_fire(speed: fx, mirror: int) {
    sh_reset(0);
    sh_sprite(0, TH15_RICE, 6);
    sh_ring(0, 1);
    sh_aim(0, 0);
    sh_count(0, 16, 1);
    sh_speed(0, speed, 0fx);
    sh_dist(0, 0fx - 4fx * speed);  // sh_dist is along each bullet's own angle
    wait(10);                       // GirlA03_at2 wait(10)
    for n in 0..10 {
        var base: angle = (rand(65536) - 32768) as angle;  // %RANDRAD
        if mirror != 0 { base = 180deg - base; }          // mirror also reflects firing angle
        sh_angle(0, base, 0deg);        // mode3 ring: etAngle spread is per-layer only (M=1)
        sh_fire(0);
        wait(1 + rand(20));             // wait(1 + ($RAND % 20))
    }
}

// GirlA03_at: hurtbox 24/24 -> r12, hitbox 16/16 -> r8.
// moveVel(22.5deg, 3.2) -> moveVelTime(120,mode1,90deg,2.0) -> moveVelTime(60,mode4,-168.75deg,4.0).
// enmCreateM gives the right-hand enemy mirror=1; its movement/firing angles reflect about vertical.
async sub girl(speed: fx, mirror: int) {
    set_invuln(65535);
    set_hurtbox(12fx);
    set_hitbox(8fx);
    spawn girl_fire(speed, mirror);
    var a1: angle = 22.5deg;
    var a3: angle = -168.75deg;
    if mirror != 0 {
        a1 = 180deg - a1;
        a3 = 180deg - a3;
    }
    move_vel(0, a1, 3.2fx, EASE_LINEAR);
    move_vel(120, 90deg, 2.0fx, EASE_LINEAR);
    wait(120);
    move_vel(60, a3, 4.0fx, EASE_QUAD_OUT);
    loop { wait(1000); }               // source waits 1000 forever; do not return (D9)
}

// MainSub04: pair schedule and F0 growth. RANDF2*8 -> signed fx offset in [-8,8).
async sub pattern() {
    wait(OPENING_BUFFER);
    var speed: fx = 1.6fx;
    for pair in 0..40 {
        var off: fx = ((rand(65536) - 32768) as fx) / 4096;
        _ = spawn_enemy(-150fx + off, -16fx, 50, 0, 0, 0, girl(speed, 0));
        wait(20);
        off = ((rand(65536) - 32768) as fx) / 4096;
        _ = spawn_enemy(150fx + off, -16fx, 50, 0, 0, 0, girl(speed, 1));
        wait(20);
        speed = speed + 0.013fx;       // %F0 = %F0 + 0.013
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}

